import { createContext, useContext, useEffect, useState } from "react";

// 컨텍스트 타입 정의
interface WalletContextType {
    isWalletConnected: boolean;
    walletName: string;
    setIsWalletConnected: (isWalletConnected: boolean) => void;
    setWalletName: (walletName: string) => void;
    publicKey: string | null;
    setPublicKey: (publicKey: string | null) => void;
}

// 초기값에 walletName과 setWalletName 추가
export const WalletContext = createContext<WalletContextType>({
    isWalletConnected: false,
    walletName: '',
    setIsWalletConnected: () => {},
    setWalletName: () => {},
    publicKey: null,
    setPublicKey: () => {},
});

export const useWalletContext = () => {
    return useContext(WalletContext); 
};

export const WalletContextProvider = ({ children }: { children: React.ReactNode }) => {
    const [isWalletConnected, setIsWalletConnected] = useState(false);
    const [walletName, setWalletName] = useState('');
    const [publicKey, setPublicKey] = useState<string | null>(null);
    // 컴포넌트 마운트 시 한 번만 실행
    useEffect(() => {
        const checkWalletConnection = () => {
            const hasConnectedWallet = localStorage.getItem('walletName') !== null;
            const storedWalletName = localStorage.getItem('walletName');
            const storedPublicKey = localStorage.getItem('publicKey');
            console.log('walletName', storedWalletName);
            console.log('Wallet connection check:', hasConnectedWallet);
            
            setIsWalletConnected(hasConnectedWallet);
            if (storedWalletName) {
                setWalletName(storedWalletName);
            }
            if (storedPublicKey) {
                setPublicKey(storedPublicKey);
            }
        };
        
        // 초기 확인
        checkWalletConnection();
        
        // 로컬 스토리지 변경 이벤트 리스너 추가
        const handleStorageChange = (e: StorageEvent) => {
            console.log('Storage changed:', e.key, e.newValue);
            checkWalletConnection();
        };
        
        window.addEventListener('storage', handleStorageChange);
        
        // 클린업 함수
        return () => {
            window.removeEventListener('storage', handleStorageChange);
        };
    }, []); // 빈 의존성 배열 - 컴포넌트 마운트 시 한 번만 실행
    
    // setWalletName을 컨텍스트 값에 추가
    return (
        <WalletContext.Provider value={{ 
            isWalletConnected, 
            setIsWalletConnected, 
            walletName, 
            setWalletName,
            publicKey,
            setPublicKey
        }}>
            {children}
        </WalletContext.Provider>
    );
};
