import { WalletList, WalletItem } from "../../styles/common/Wallet"
import { ButtonMedium } from "../../styles/common/Button"
import { theme } from "../../styles/theme"
import { useEffect, useState } from "react";
import { useWalletContext } from "../../contexts/WalletContextProvider";
import { detectMobileDevice } from '../../utils/sizeUtils';
import { walletText } from '../../utils/wallet/walletText';
import MessageModal from "../modal/MessageModal";
import { MetaMaskSDK } from "@metamask/sdk"

interface TokenBalance {
    mint: string;
    symbol: string;
    amount: number;
}
export default function MetaMaskWallet() {
    const walletName = 'MetaMask';
    const [actionType, setActionType] = useState<string>('');
    const [isOpen, setIsOpen] = useState<boolean>(false);
    const [connected, setConnected] = useState<boolean>(false);
    const [tokenBalances, setTokenBalances] = useState<TokenBalance[]>([]);
    const [isMobile, setIsMobile] = useState<boolean>(false);
    const [isMetaMaskInstalled, setIsMetaMaskInstalled] = useState<boolean>(false);
    const { setIsWalletConnected, setWalletName, isWalletConnected, setPublicKey } = useWalletContext();
    const [MMSDK, setMMSDK] = useState<any>(null);
    const [accounts, setAccounts] = useState<string[]>([]);
    const [solanaAccounts, setSolanaAccounts] = useState<string[] | null | any | any[]>([]);

    useEffect(() => {
        const MMSDK = new MetaMaskSDK({
            dappMetadata: {
                name: "SIGX",
                url: window.location.href,
            },
        });
        setMMSDK(MMSDK);
    }, []);

    // 솔라나 스냅 설치 확인 및 설치 요청 함수
    const checkAndInstallSolanaSnap = async (provider: any) => {
        try {
            // 먼저 설치된 스냅 목록 확인
            const installedSnaps = await provider.request({
                method: 'wallet_getSnaps'
            });
            
            console.log("Installed snaps:", installedSnaps);
            
            // 솔라나 스냅이 이미 설치되어 있는지 확인
            const solanaSnapId = 'npm:@metamask/solana-snap';
            const isInstalled = Object.keys(installedSnaps || {}).includes(solanaSnapId);
            
            if (isInstalled) {
                console.log("Solana snap is already installed");
                return true;
            }
            
            // 스냅이 설치되어 있지 않은 경우 설치 요청
            console.log("Requesting Solana snap installation...");
            await provider.request({
                method: 'wallet_requestSnaps',
                params: {
                    [solanaSnapId]: {}
                }
            });
            
            console.log("Solana snap installed successfully");
            return true;
        } catch (error: any) {
            console.error("Error in checkAndInstallSolanaSnap:", error);
            
            if (error.code === 4100) {
                console.log("User denied authorization for the Solana snap");
                // 사용자에게 권한 거부에 대한 알림 표시
                setActionType('snapAuthDenied');
                setIsOpen(true);
            } else if (error.code === 4001) {
                console.log("User rejected the snap installation");
                setActionType('snapInstallRejected');
                setIsOpen(true);
            }
            
            return false;
        }
    };

    // 솔라나 계정 정보 가져오기
    const getSolanaAccounts = async (provider: any) => {
        try {
            // 먼저 스냅이 설치되어 있는지 확인
            const installedSnaps = await provider.request({
                method: 'wallet_getSnaps'
            });
            
            const solanaSnapId = 'npm:@metamask/solana-snap';
            const isInstalled = Object.keys(installedSnaps || {}).includes(solanaSnapId);
            
            if (!isInstalled) {
                console.log("Solana snap is not installed");
                return [];
            }
            
            // 스냅이 설치되어 있으면 계정 정보 요청
            const solAccounts = await provider.request({
                method: 'wallet_invokeSnap',
                params: {
                    snapId: solanaSnapId,
                    request: {
                        method: 'getAccounts'
                    }
                }
            });
            
            console.log('Solana accounts:', solAccounts);
            return solAccounts;
        } catch (error: any) {
            console.error("Error in getSolanaAccounts:", error);
            
            if (error.code === 4100) {
                console.log("User denied authorization for getting Solana accounts");
                // 사용자에게 알림
                setActionType('solanaAccountsDenied');
                setIsOpen(true);
            }
            
            return [];
        }
    };

    // 솔라나 토큰 잔액 가져오기
    const getSolanaTokenBalances = async (provider: any, solanaAddress: string) => {
        try {
            const tokenBalances = await provider.request({
                method: 'wallet_invokeSnap',
                params: {
                    snapId: 'npm:@metamask/solana-snap',
                    request: {
                        method: 'getTokenAccounts',
                        params: {
                            account: solanaAddress
                        }
                    }
                }
            });
            
            console.log('Solana token balances:', tokenBalances);
            return tokenBalances;
        } catch (error) {
            console.error("솔라나 토큰 잔액 가져오기 실패:", error);
            return [];
        }
    };

    const connectMM = async () => {
        try {
            if (isWalletConnected) {
                setActionType('alreadyConnected');
                setIsOpen(true);
                return;
            }
            
            // connectAndSign 사용
            const ethAccounts = await MMSDK.connectAndSign({
                msg: "Sign in to SIGX"
            });
            console.log('Ethereum accounts:', ethAccounts);
            
            // 연결 후 provider 접근
            const provider = MMSDK.getProvider();
            // if (!provider) {
            //     console.error("메타마스크 제공자를 가져올 수 없습니다.");
            //     // 계속 진행 (provider가 없어도 이미 연결은 됨)
            // } else {
            //     try {
            //         // 솔라나 스냅 설치 확인 및 설치
            //         const isSnapInstalled = await checkAndInstallSolanaSnap(provider);
                    
            //         if (isSnapInstalled) {
            //             // 솔라나 계정 정보 가져오기
            //             const solAccounts = await getSolanaAccounts(provider);
            //             if (solAccounts && solAccounts.length > 0) {
            //                 setSolanaAccounts(solAccounts);
                            
            //                 // 솔라나 계정이 있으면 토큰 잔액 가져오기
            //                 try {
            //                     const solAddress = solAccounts[0].address;
            //                     const tokenBalances = await getSolanaTokenBalances(provider, solAddress);
            //                     setTokenBalances(tokenBalances);
            //                 } catch (tokenError) {
            //                     console.error("토큰 잔액 가져오기 실패:", tokenError);
            //                 }
            //             }
            //         }
            //     } catch (snapError) {
            //         console.error("Solana snap interaction failed:", snapError);
            //         // 스냅 관련 오류가 있어도 이더리움 연결은 계속 진행
            //     }
            // }
            
            // 상태 업데이트
            setAccounts(Array.isArray(ethAccounts) ? ethAccounts : [ethAccounts]);
            setIsMetaMaskInstalled(true);
            setPublicKey(Array.isArray(ethAccounts) ? ethAccounts[0] : ethAccounts);
            setConnected(true);
            localStorage.setItem('publicKey', Array.isArray(ethAccounts) ? ethAccounts[0] : ethAccounts);
            localStorage.setItem('walletName', 'MetaMask');
            setWalletName('MetaMask');
            setIsWalletConnected(true);
            setIsOpen(true);
            setActionType('connect');
            
        } catch (error: any) {
            console.error('Error connecting to MetaMask:', error);
            if (error.code === 4001) {
                setActionType('userRejected');
                setIsOpen(true);
            } else if (error.code === -32002) {
                setActionType('alreadyPending');
                setIsOpen(true);
            } else {
                setActionType('connectError');
                setIsOpen(true);
            }
        }
    };

    return (
        <>
            <WalletList onClick={() => { connectMM() }}>
                <WalletItem>
                    <img src={theme.icon.metamask} alt="metamask" />
                    <p>MetaMask</p>
                </WalletItem>
                <WalletItem className="status-item">
                    {
                        isMetaMaskInstalled ? (
                            <ButtonMedium bgColor={theme.color.walletBg} textColor={theme.color.mainGreen} borderColor="none">
                                <span>CONNECTED</span>
                            </ButtonMedium>
                        ) : (
                            <ButtonMedium bgColor="rgba(255, 255, 255, 0.15)" textColor={theme.color.gray} borderColor="none">
                                <span>NOT CONNECTED</span>
                            </ButtonMedium>
                        )
                    }
                    <img src={theme.icon.rightArrow} alt="right-arrow" />
                </WalletItem>
            </WalletList>
            
            {/* 솔라나 계정 및 토큰 정보 표시 */}
            {connected && solanaAccounts.length > 0 && (
                <div className="solana-info">
                    <h3>Solana Accounts</h3>
                    {solanaAccounts.map((account:any, index:any) => (
                        <div key={index} className="solana-account">
                            <p>Address: {account.address}</p>
                        </div>
                    ))}
                    
                    {tokenBalances.length > 0 && (
                        <>
                            <h3>Solana Tokens</h3>
                            {tokenBalances.map((token, index) => (
                                <div key={index} className="token-balance">
                                    <p>{token.symbol}: {token.amount}</p>
                                </div>
                            ))}
                        </>
                    )}
                </div>
            )}
            
            <MessageModal 
                action={actionType} 
                isOpen={isOpen} 
                setIsOpen={setIsOpen} 
                walletName={walletName} 
                title={walletText(walletName, actionType)?.title} 
                content={walletText(walletName, actionType)?.content} 
            />
        </>
    )
}