export const walletText = (walletName:string,action:string)  => {
    if(action === 'prepare'){
        return {
            title: 'Comming Soon',
            content: 'Currently being prepared',
        };
    }else if(action === 'uninstalled'){
        return {
            title: `Need to install ${walletName} Wallet`,
            content: `The ${walletName} Google extension is not installed.<br/> Would you like to go to the installation page?`,
            link:setLink(walletName)
        };
    }else if(action === 'noWallet'){
        return {
            title: `There is no ${walletName} Wallet`,
            content: 'The wallet is installed but no wallet has been created.<br/>Please create a wallet or recover an existing wallet.<br/> Please try connecting again after completing wallet setup.',
        };
    }else if(action === 'connect'){
        return {
            title: `Your wallet has been connected!`,
            content: ``,
        };
    }else if(action === 'userRejected'){
        return {
            title: `Please follow the instructions to create or connect a wallet`,
            content: `Please follow the instructions to create or connect a wallet. <br/>You will need to download the app and set up account.`,
        };
    }else if(action === 'needReload'){
        return {
            title: `Please reload the page`,
            content: `After installing the wallet, please reload the page.`,
        };
    }else if(action === 'alreadyConnected'){
        return {
            title: `Already connected`,
            content: `The wallet is already connected. <br/> You can connect another wallet after disconnecting <br/>from the current wallet at the top right of the wallet menu.`,
        };
    }else if(action === 'alreadyPending'){
        return {
            title: `Request of type 'wallet_requestPermissions' already pending`,
            content: `Please check your wallet app for pending requests.`,
        };
    }else if(action === 'snapAuthDenied'){
        return {
            title: `${walletName} 솔라나 스냅 권한 거부됨`,
            content: '솔라나 스냅에 대한 권한이 거부되었습니다. 솔라나 자산을 보려면 메타마스크 설정에서 권한을 허용해주세요.'
        };
    }else if(action === 'snapInstallRejected'){
        return {
            title: `${walletName} 솔라나 스냅 설치 거부됨`,
            content: '솔라나 스냅 설치가 거부되었습니다. 솔라나 자산을 보려면 스냅을 설치해야 합니다.'
        };
    }else if(action === 'solanaAccountsDenied'){
        return {
            title: `${walletName} 솔라나 계정 접근 거부됨`,
            content: '솔라나 계정 정보에 대한 접근이 거부되었습니다. 솔라나 자산을 보려면 계정 접근을 허용해주세요.'
        };
    }
};


const setLink = (walletName:string) => {
    if(walletName === 'Phantom'){
        return 'https://chromewebstore.google.com/detail/phantom/bfnaelmomeimhlpmgjnjophhpkkoljpa'
    }else if(walletName === 'OKX'){
        return 'https://chromewebstore.google.com/detail/okx-wallet/mcohilncbfahbmgdjkbpemcciiolgcge'
    }
}