export default function AIChartSignal({ id }: { id: string }) {
    const [isOpen, setIsOpen] = useState(false);
    const [isSufficientCoin, setIsSufficientCoin] = useState(false);

    const { data: candleData, isLoading: candleLoading, error: candleError } = useCandleData(
        '/candle/candle',
        'BTCUSDT',
        0
    );
    // console.log(candleData);

    const { data: signalData, isLoading: signalLoading, error: signalError } = useCandleSignalData(
        '/analysis/signal',
        'BTCUSDT',
        0
    );
    // console.log(signalData);
    let afterLastCandle: null | { time: number, open: number, high: number, low: number, close: number } = null;
    let beforeLastCandle: null | { time: number, open: number, high: number, low: number, close: number } = null;
    let percent = 0;
    if (candleData && candleData.candleData && candleData.candleData.length > 0) {
        afterLastCandle = candleData.candleData[candleData.candleData.length - 1];
        beforeLastCandle = candleData.candleData[candleData.candleData.length - 2];
        if (beforeLastCandle && afterLastCandle) {
            percent = ((afterLastCandle.close - beforeLastCandle.close) / beforeLastCandle.close) * 100;
        }
    }

    return (
        <Wrapper id={id}>
            <ContainerWrapper>
                <TitleWrapper>
                    <Title title="AI CHART" margin="0.5rem" />
                    <h1>AI Chart Signals</h1>
                    <h4 className="text-gray">The best trading signal predicted by AI, check it out for yourself!</h4>
                </TitleWrapper>
            </ContainerWrapper>
            <Container className="bg-blur">
                <ContainerWrapper>
                    <ChartContainer>
                        <div className="chart-header">
                            <h4 className="symbol-info">
                                <img src={`${process.env.PUBLIC_URL}/assets/images/coin_logos/btc.png`} />
                                BTC <span className="text-gray"> / USDT</span>
                            </h4>
                            <div className="price-info">
                                <h4 className={colorFormat(afterLastCandle?.close || 0)}>
                                    {afterLastCandle ? numberFormat(afterLastCandle.close) : 0}
                                </h4>
                                <p className={colorFormat(percent || 0)}>{percentFormat(percent || 0)}</p>
                            </div>
                        </div>
                        <div className="chart-container">
                            <SignalChart candleData={candleData} signalData={signalData} />
                        </div>
                        <div className="btn-wrapper">
                            <Button onClick={() => setIsOpen(true)}>
                                {
                                    isSufficientCoin ?
                                        <Link to="/ai-chart/BTCUSDT" >
                                            View AI Chart
                                        </Link>
                                        :
                                        <a>View AI Chart</a>
                                }
                            </Button>
                        </div>
                    </ChartContainer>
                </ContainerWrapper>
            </Container>
            <MessageModal
                title="The amount of SGX coins you have is insufficient."
                content="To use this service for free, you must have <span className='text-green'>1,000 SGX </span>coins."
                action="close"
                isOpen={isOpen}
                setIsOpen={setIsOpen}
            />
        </Wrapper>
    );
}